import java.util.*;

public class Main {
    static List<Integer>[] e = new ArrayList[2020];
    static int[][] ir = new int[20][20];
    static int[][] sc = new int[20][20];
    static int[][] pc = new int[20][20];
    static char[][] s = new char[20][20];
    static char[][] p = new char[20][20];
    static int[][] dd = new int[20][20];
    static int[] dx = {0, 1, -1, 0};
    static int[] dy = {1, 0, 0, -1};
    static List<Integer>[][] ns = new ArrayList[20][20];
    static List<Integer>[][] np = new ArrayList[20][20];

    static int sp, pp;
    static int[] ds = new int[2020];
    static int[] pa = new int[2020];

    static int n, t;
    static int rx, ry;

    static {
        for (int i = 0; i < 2020; i++) {
            e[i] = new ArrayList<>();
        }
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 20; j++) {
                ns[i][j] = new ArrayList<>();
                np[i][j] = new ArrayList<>();
            }
        }
    }

    static void ade(int a, int b) {
        e[a].add(b);
        e[b].add(a);
    }

    static boolean bfs() {
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= sp; i++) {
            if (pa[i] == 0) {
                ds[i] = 0;
                q.offer(i);
            } else {
                ds[i] = 3010;
            }
        }
        ds[0] = 3010;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (ds[u] < ds[0]) {
                for (int v : e[u]) {
                    int vpa = pa[v];
                    if (ds[vpa] > ds[u] + 1) {
                        ds[vpa] = ds[u] + 1;
                        q.offer(vpa);
                    }
                }
            }
        }
        return ds[0] != 3010;
    }

    static boolean dfs(int x) {
        if (x == 0) return true;
        for (int v : e[x]) {
            int u = pa[v];
            if (ds[u] == ds[x] + 1) {
                if (dfs(u)) {
                    pa[x] = v;
                    pa[v] = x;
                    return true;
                }
            }
        }
        return false;
    }

    static int hkp() {
        int an = 0;
        while (bfs()) {
            for (int i = 1; i <= sp; i++) {
                if (pa[i] == 0) {
                    an += dfs(i) ? 1 : 0;
                }
            }
        }
        return an;
    }

    static void wk(int a, int b) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                dd[i][j] = 100000;
            }
        }
        Deque<int[]> q = new ArrayDeque<>();
        dd[a][b] = 0;
        q.offer(new int[]{a, b});
        while (!q.isEmpty()) {
            int[] x = q.poll();
            int xX = x[0], y = x[1];
            for (int[] dir : new int[][]{{0,1},{1,0},{-1,0},{0,-1}}) {
                int nx = xX + dir[0];
                int ny = y + dir[1];
                if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                    if (sc[nx][ny] != -1 && dd[nx][ny] > dd[xX][y] + 1 && dd[xX][y] + 1 <= ir[nx][ny]) {
                        dd[nx][ny] = dd[xX][y] + 1;
                        q.offer(new int[]{nx, ny});
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner scn = new Scanner(System.in);
        n = scn.nextInt();
        t = scn.nextInt();

        for (int i = 1; i <= n; i++) {
            Arrays.fill(ir[i], 0);
            Arrays.fill(sc[i], 0);
            Arrays.fill(pc[i], 0);
            Arrays.fill(s[i], ' ');
            Arrays.fill(p[i], ' ');
        }

        for (int i = 1; i <= n; i++) {
            String row = scn.next();
            s[i] = (" " + row).toCharArray();
        }
        for (int i = 1; i <= n; i++) {
            String row = scn.next();
            p[i] = (" " + row).toCharArray();
        }

        rx = 1; ry = 1;
        sp = 1; pp = 1000;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (s[i][j] == 'Z' || s[i][j] == 'Y') {
                    sc[i][j] = -1;
                    ir[i][j] = 0;
                }
                if (s[i][j] == 'Z') {
                    rx = i; ry = j; ir[i][j] = 0;
                }
                if ('0' <= s[i][j] && s[i][j] <= '9') {
                    sc[i][j] = s[i][j] - '0';
                }
                for (int k = 0; k < sc[i][j]; k++) {
                    ns[i][j].add(sp++);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if ('0' <= p[i][j] && p[i][j] <= '9') {
                    pc[i][j] = p[i][j] - '0';
                }
                for (int k = 0; k < pc[i][j]; k++) {
                    np[i][j].add(pp++);
                }
            }
        }

        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{rx, ry});
        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int x = pos[0], y = pos[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                    if (ir[nx][ny] > ir[x][y] + 1 && sc[nx][ny] != -1) {
                        ir[nx][ny] = ir[x][y] + 1;
                        q.offer(new int[]{nx, ny});
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (sc[i][j] > 0) {
                    wk(i, j);
                }
            }
        }

        System.out.println(hkp());
        scn.close();
    }
}
